<script setup lang="ts">
import { ui } from "../ui"
import DateTime from '../components/DateTime.vue'
import { computed,reactive,ref,watch,onMounted,onUnmounted } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import { ArrowLeftIcon,ChevronDownIcon,ArrowPathIcon } from '@heroicons/vue/24/outline'
import GitHubPanel from '../components/GitHubPanel.vue'
import NotesPanel from '../components/NotesPanel.vue'
import AssignmentPanel from '../components/AssignmentPanel.vue'
import ContextActivity from '../components/ContextActivity.vue'
import { makeNoteDraft,noteDirty,activityLabel } from '../composables/collaboration'
import { bootstrap,api,notify,ApiError } from '../composables/api'
import { useInvestigation,queryString,date,zone } from '../composables/investigation'
import type { DetailResult,Frame } from '../types'
const route=useRoute(),router=useRouter(),{data,loading,error,reload}=useInvestigation<DetailResult>(()=>'/issues/'+route.params.issue+'?'+queryString(route.query,['returnTo','tab']))
const noteDraft=reactive(makeNoteDraft())
function leaveNotes(){return !noteDirty(noteDraft)||window.confirm('Discard your unsaved note draft before leaving this error?')}
onBeforeRouteLeave(leaveNotes)
onBeforeRouteUpdate((to,from)=>to.params.issue===from.params.issue||leaveNotes())
const noteUnload=(e:BeforeUnloadEvent)=>{if(noteDirty(noteDraft)){e.preventDefault();e.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',noteUnload));onUnmounted(()=>window.removeEventListener('beforeunload',noteUnload))
const tab=computed(()=>typeof route.query.tab==='string'?route.query.tab:'stack'),vendor=ref(false),snoozing=ref(false),duration=ref('24'),custom=ref(''),acting=ref(false),conflict=ref('')
const selected=computed(()=>data.value?.selected), payload=computed(()=>selected.value?.evidence)
const back=computed(()=>typeof route.query.returnTo==='string'&&/^\/(errors|overview)(\?|$)/.test(route.query.returnTo)?route.query.returnTo:'/errors')
const frames=computed<Frame[]>(()=>payload.value?[{file:payload.value.exception.file,line:payload.value.exception.line,class:payload.value.exception.class,source_url:selected.value?.source_url},...payload.value.exception.trace]:[])
const isVendor=(f:Frame)=>f.file.startsWith('vendor/')||f.file.includes('/vendor/')
const visibleFrames=computed(()=>vendor.value?frames.value:frames.value.filter(f=>!isVendor(f)))
watch(()=>route.params.issue,()=>{conflict.value='';snoozing.value=false;vendor.value=false;Object.assign(noteDraft,makeNoteDraft())})
watch(()=>selected.value?.id,(id)=>{if(id&&!route.query.occurrence)router.replace({query:{...route.query,occurrence:id}})})
function choose(id:string){router.replace({query:{...route.query,occurrence:id}})}
function page(n:number){router.replace({query:{...route.query,page:String(n)}})}
let attempt:{intent:string;key:string;until?:string}|null=null
async function act(action:string){if(!data.value||acting.value)return;acting.value=true;conflict.value=''
 try {let until:string|undefined;if(action==='snooze'){if(duration.value==='custom'){if(!/(Z|[+-]\d{2}:\d{2})$/i.test(custom.value)||Number.isNaN(Date.parse(custom.value)))throw new Error('Enter a future ISO date and time with a UTC offset.');until=new Date(custom.value).toISOString()}else until=new Date(Date.now()+Number(duration.value)*3600000).toISOString()}
 const intent=JSON.stringify([data.value.issue.id,data.value.issue.state_version,action,duration.value,custom.value]);if(attempt?.intent!==intent)attempt={intent,key:crypto.randomUUID(),until};until=attempt.until
 await api('/issues/'+data.value.issue.id+'/actions','POST',{client_key:attempt.key,version:data.value.issue.state_version,action,...(until?{until}:{})});attempt=null;snoozing.value=false;notify('Error state updated.');await reload()
 }catch(e){if(e instanceof ApiError && e.status<500)attempt=null;if(e instanceof ApiError && e.status===409)conflict.value=e.message;else notify(e instanceof Error?e.message:'The action could not be completed.',true)}finally{acting.value=false}
}
</script>
<template><RouterLink :to="back" :class="ui('$all', '$a', 'back-link')"><ArrowLeftIcon :class="ui('$all', '$svg')"/>Back to filtered errors</RouterLink><p v-if="loading" role="status" :class="ui('$all', '$p', 'loading-message')">Loading occurrence…</p><div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert">{{ error }}<button :class="ui('$all', '$button', 'button')" @click="reload">Try again</button></div><template v-if="data"><div :class="ui('$all', '$div', 'error-heading')"><div :class="ui('$all', '$div')"><div :class="ui('$all', '$div', 'issue-identifiers')"><span :class="ui('$all', '$span', 'status-badge', ('status-'+data.issue.status))" >{{data.issue.status}}</span><span v-if="data.issue.regressions" :class="ui('$all', '$span', 'badge')">Regression</span><span v-if="data.issue.is_test" :class="ui('$all', '$span', 'badge')">Test event</span><span v-if="data.issue.recovered_only" :class="ui('$all', '$span', 'badge')" title="Only historical or recovered occurrences so far">Historical</span><span :class="ui('$all', '$span')">{{ selected?.origin??'Unknown origin' }} · {{data.issue.environment}}</span></div><h1 :class="ui('$all', '$h1')" :title="data.issue.message">{{data.issue.message || data.issue.class}}</h1><p :class="ui('$all', '$p')">{{data.issue.class}} · <span :class="ui('$all', '$span', 'code')">{{data.issue.file}}:{{data.issue.line}}</span></p></div><div v-if="bootstrap?.capabilities.operate" :class="ui('$all', '$div', 'lifecycle-actions')"><button v-if="data.issue.status==='unresolved'" :class="ui('$all', '$button', 'button primary')" :disabled="acting" @click="act('resolve')">Resolve</button><button v-if="['resolved','ignored'].includes(data.issue.status)" :class="ui('$all', '$button', 'button primary')" :disabled="acting" @click="act('reopen')">Reopen</button><button v-if="data.issue.status==='unresolved'" :class="ui('$all', '$button', 'button')" :disabled="acting" :aria-expanded="snoozing" @click="snoozing=!snoozing">Snooze</button><button v-if="data.issue.status==='snoozed'" :class="ui('$all', '$button', 'button primary')" :disabled="acting" @click="act('unsnooze')">Unsnooze</button><button v-if="data.issue.status!=='ignored'" :class="ui('$all', '$button', 'button')" :disabled="acting" @click="act('ignore')">Ignore</button><button :class="ui('$all', '$button', 'button icon-button')" aria-label="Refresh error" :disabled="acting" @click="reload"><ArrowPathIcon :class="ui('$all', '$svg')"/></button></div></div><div v-if="conflict" :class="ui('$all', '$div', 'notice warning')" role="alert">{{conflict}}<button :class="ui('$all', '$button', 'button')" @click="conflict='';reload()">Reload current error</button></div><form v-if="snoozing" :class="ui('$all', '$form', 'snooze-form')" @submit.prevent="act('snooze')"><label :class="ui('$all', '$label', 'field')">Snooze duration<select :class="ui('$all', '$select')" v-model="duration"><option :class="ui('$all', '$option')" value="1">1 hour</option><option :class="ui('$all', '$option')" value="24">24 hours</option><option :class="ui('$all', '$option')" value="168">7 days</option><option :class="ui('$all', '$option')" value="custom">Future date and time</option></select></label><label v-if="duration==='custom'" :class="ui('$all', '$label', 'field')">Future time with UTC offset<input :class="ui('$all', '$input')" v-model="custom" placeholder="2026-11-12T12:00:00+05:30" required><small :class="ui('$all', '$small')">Displayed timezone: {{zone()}}. An explicit offset avoids ambiguous daylight-saving times.</small></label><p :class="ui('$all', '$p', 'help')">Occurrences keep counting. Automatic occurrence alerts are suppressed until expiry; an in-flight external send cannot be recalled.</p><button :class="ui('$all', '$button', 'button primary')" :disabled="acting">Confirm snooze</button><button :class="ui('$all', '$button', 'button')" type="button" @click="snoozing=false">Cancel</button></form><div v-if="data.issue.status==='snoozed'" :class="ui('$all', '$div', 'notice neutral')">Snoozed until <DateTime :class="ui('$all', '$DateTime')" :value="data.issue.snoozed_until"/> · {{zone()}}</div><nav :class="ui('$all', '$nav', 'detail-tabs')" aria-label="Investigation sections"><RouterLink v-for="(name,key) in {stack:'Stack trace',context:'Context & activity',insights:'Insights',activity:'Notes & activity',links:'Linked issues'}" :key="key" :class="ui('$all', '$a', ({selected:tab===key}))" :aria-current-value="tab===key?'page':'false'" :to="{query:{...route.query,tab:key}}">{{name}}</RouterLink></nav><div :class="ui('$all', '$div', 'investigation-grid', ({'has-assignment':bootstrap?.features.assignments}))" ><AssignmentPanel :class="ui('$all', '$AssignmentPanel')" v-if="bootstrap?.features.assignments" :issue="data.issue" @changed="reload"/><section :class="ui('$all', '$section', 'panel occurrence-panel')"><div :class="ui('$all', '$div', 'selected-heading')"><span :class="ui('$all', '$span')">Selected occurrence</span><h2 :class="ui('$all', '$h2')"><DateTime :class="ui('$all', '$DateTime')" v-if="selected" :value="selected.occurred_at"/><template v-else>No occurrence available</template> <small :class="ui('$all', '$small')">{{zone()}}</small></h2><span v-if="selected?.mode!=='live'" :class="ui('$all', '$span', 'badge')">{{selected?.mode==='historical_import'?'Historical import':selected?.mode}}</span><p v-if="selected?.mode==='historical_import'" :class="ui('$all', '$p', 'help')">Imported from Telescope history. Original reportability and deployment release were not verified. No retrospective alert was generated.</p></div><div v-if="!payload && ['stack','context'].includes(tab)" :class="ui('$all', '$div', 'evidence-unavailable')"><h3 :class="ui('$all', '$h3')">{{selected?.evidence_state==='expired'?'Retained evidence expired':selected?.evidence_state==='decryption_failed'?'Retained evidence could not be decrypted':'No retained snapshot'}}</h3><p :class="ui('$all', '$p')">The error summary and occurrence identity remain available. Choose another retained occurrence from the history.</p><RouterLink v-if="bootstrap?.capabilities.manage" to="/settings/health" :class="ui('$all', '$a', 'text-link')">Review system health</RouterLink></div><template v-else><p v-if="payload" :class="ui('$all', '$p', 'exception-message')">{{payload.exception.message}}</p><template v-if="tab==='stack' && payload"><div v-if="!frames.length" :class="ui('$all', '$div', 'notice neutral')">Stack trace {{payload.coverage.trace??'unavailable'}}.</div><div :class="ui('$all', '$div', 'stack-frames')"><div v-for="(frame,index) in visibleFrames" :key="index" :class="ui('$all', '$div', 'stack-frame', ({application:!isVendor(frame)}))" ><span :class="ui('$all', '$span', 'frame-number')">{{index}}</span><div :class="ui('$all', '$div')"><strong :class="ui('$all', '$strong')">{{frame.class??''}}{{frame.function?'::'+frame.function+'()':''}}</strong><div :class="ui('$all', '$div', 'code')"><a :class="ui('$all', '$a')" v-if="frame.source_url" :href="frame.source_url" target="_blank" rel="noopener noreferrer">{{frame.file}}:{{frame.line}}</a><span :class="ui('$all', '$span')" v-else>{{frame.file}}:{{frame.line}}</span></div></div></div><button v-if="frames.some(isVendor)" :class="ui('$all', '$button', 'vendor-toggle')" :aria-expanded="vendor" @click="vendor=!vendor"><ChevronDownIcon :class="ui('$all', '$svg')"/>{{vendor?'Hide':'Show'}} {{frames.filter(isVendor).length}} vendor frames</button></div><p :class="ui('$all', '$p', 'help')">Trace coverage: {{payload.coverage.trace}}. Code previews are not read from the currently deployed filesystem. Source links require a captured immutable release and code-host mapping.</p></template><template v-else-if="tab==='context' && payload"><ContextActivity :class="ui('$all', '$ContextActivity')" :evidence="payload" :telescope-url="selected?.telescope_url"/></template><template v-else-if="tab==='insights'"><h3 :class="ui('$all', '$h3')">Retained evidence insights</h3><p :class="ui('$all', '$p')">{{data.insights.retained_count}} snapshots · <DateTime :class="ui('$all', '$DateTime')" :value="data.insights.from"/> to <DateTime :class="ui('$all', '$DateTime')" :value="data.insights.to"/></p><div v-for="name in ['origin','route','release','tags'] as const" :key="name" :class="ui('$all', '$div', 'insight-block')"><h3 :class="ui('$all', '$h3')">{{name}}</h3><ul :class="ui('$all', '$ul')"><li :class="ui('$all', '$li')" v-for="entry in data.insights.breakdowns[name]" :key="entry.value">{{entry.value}} <strong :class="ui('$all', '$strong')">{{entry.count}}</strong></li></ul><p :class="ui('$all', '$p')" v-if="!data.insights.breakdowns[name].length">No retained {{name}} snapshot was available.</p></div><p :class="ui('$all', '$p')">Affected users: {{data.insights.breakdowns.users?data.insights.breakdowns.users+' pseudonymous identifiers':'Unavailable or excluded by policy'}}</p><p :class="ui('$all', '$p', 'help')">{{data.insights.coverage}}</p></template><template v-else-if="tab==='activity'"><NotesPanel :class="ui('$all', '$NotesPanel')" v-if="bootstrap?.features.collaboration" :issue="data.issue.id" :draft="noteDraft" @changed="reload"/><p v-else :class="ui('$all', '$p', 'notice neutral')">Publish and run the collaboration migration to enable notes.</p><h3 :class="ui('$all', '$h3', 'activity-title')">Activity</h3><p :class="ui('$all', '$p', 'help')">Showing the latest 100 activity entries. Note text is not duplicated here.</p><ul :class="ui('$all', '$ul', 'activity-list')"><li :class="ui('$all', '$li')" v-for="a in data.activity" :key="a.id"><div :class="ui('$all', '$div')"><strong :class="ui('$all', '$strong')">{{activityLabel(a.type)}}</strong><p :class="ui('$all', '$p', 'help')">{{a.actor}}<template v-if="a.metadata.previous||a.metadata.status"> · {{a.metadata.previous}} {{a.metadata.status?'→ '+a.metadata.status:''}}</template></p></div><p v-if="['error.assigned','error.unassigned'].includes(a.type)" :class="ui('$all', '$p', 'help')">Assignee: {{a.metadata.assignee_label??'Unassigned'}}<span :class="ui('$all', '$span')" v-if="a.metadata.previous_assignee_label"> (previously {{a.metadata.previous_assignee_label}})</span></p><DateTime :class="ui('$all', '$DateTime')" :value="a.at"/></li></ul></template><template v-else><GitHubPanel :class="ui('$all', '$GitHubPanel')" :issue="data.issue.id"/></template></template></section><aside :class="ui('$all', '$aside', 'detail-rail')"><section :class="ui('$all', '$section', 'panel')"><h2 :class="ui('$all', '$h2')">Error summary</h2><dl :class="ui('$all', '$dl', 'summary-list')"><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Lifetime occurrences</dt><dd :class="ui('$all', '$dd')">{{data.issue.lifetime_count}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">{{data.window.range}}</dt><dd :class="ui('$all', '$dd')">{{data.issue.range_count}}</dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">First seen</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="data.issue.first_seen_at"/></dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Last seen</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="data.issue.last_seen_at"/></dd></div></dl></section><section :class="ui('$all', '$section', 'panel occurrence-picker')"><div :class="ui('$all', '$div', 'section-heading')"><h2 :class="ui('$all', '$h2')">Occurrences</h2><small :class="ui('$all', '$small')">{{data.occurrences.total}} total</small></div><label :class="ui('$all', '$label', 'field')">Selected occurrence<select :class="ui('$all', '$select')" :value="selected?.id" @change="choose(($event.target as HTMLSelectElement).value)"><option :class="ui('$all', '$option')" v-if="selected&&!data.occurrences.items.some(o=>o.id===selected!.id)" :value="selected.id">{{date(selected.occurred_at)}} · {{selected.origin}}</option><option :class="ui('$all', '$option')" v-for="o in data.occurrences.items" :key="o.id" :value="o.id">{{date(o.at)}} · {{o.origin}}{{o.release?' · '+o.release:''}}</option></select></label><details :class="ui('$all', '$details')"><summary :class="ui('$all', '$summary')">Browse occurrence history</summary><ul :class="ui('$all', '$ul', 'occurrence-history')"><li :class="ui('$all', '$li')" v-for="o in data.occurrences.items" :key="o.id"><button :class="ui('$all', '$button', 'text-link')" :aria-current="selected?.id===o.id?'true':undefined" @click="choose(o.id)"><DateTime :class="ui('$all', '$DateTime')" :value="o.at"/></button><small :class="ui('$all', '$small')">{{o.origin}} · {{o.mode==='historical_import'?'Historical import':o.mode}}{{o.release?' · '+o.release:''}}</small></li></ul><div :class="ui('$all', '$div', 'pagination')"><button :class="ui('$all', '$button', 'button')" :disabled="data.occurrences.page<=1" @click="page(data.occurrences.page-1)">Previous</button><button :class="ui('$all', '$button', 'button')" :disabled="data.occurrences.page>=data.occurrences.last_page" @click="page(data.occurrences.page+1)">Next</button></div></details></section></aside></div><p :class="ui('$all', '$p', 'data-caption')">Retained snapshot · the original Telescope entry may have been pruned. <a v-if="selected?.telescope_url" :href="selected.telescope_url" target="_blank" rel="noopener noreferrer" :class="ui('$all', '$a', 'text-link')">Open in Telescope</a><br :class="ui('$all', '$br')">Data as of <DateTime :class="ui('$all', '$DateTime')" :value="data.window.as_of"/> · {{zone()}}</p></template></template>
